from ortools.sat.python import cp_model
import numpy as np
import json

def main():
    num_consultants = 40
    num_teams = 8
    num_dimensions = 4
    team_size = 5

    technical_expertise = [4, 1, 3, 3, 4, 4, 5, 2, 3, 1, 3, 3, 1, 3, 4, 4, 3, 4, 4, 0, 
                          4, 4, 3, 2, 5, 3, 2, 2, 5, 4, 4, 4, 4, 5, 3, 4, 5, 4, 5, 4]

    leadership_capability = [4, 1, 3, 3, 2, 3, 2, 3, 4, 3, 3, 3, 3, 5, 4, 4, 2, 4, 2, 3,
                            5, 4, 4, 4, 5, 4, 3, 1, 3, 3, 3, 5, 5, 3, 4, 3, 5, 3, 3, 3]

    innovation_capacity = [2, 2, 0, 1, 2, 3, 3, 2, 3, 3, 3, 3, 3, 1, 3, 3, 4, 2, 4, 2,
                          4, 3, 2, 1, 2, 4, 3, 3, 0, 3, 3, 2, 2, 2, 4, 1, 2, 4, 2, 2]

    communication_proficiency = [3, 1, 3, 1, 3, 3, 5, 3, 4, 1, 2, 3, 4, 0, 3, 3, 4, 3, 3, 2,
                                1, 3, 2, 5, 2, 3, 1, 2, 3, 3, 4, 2, 1, 3, 3, 3, 2, 3, 3, 3]

    rating = np.zeros((num_consultants, num_dimensions), dtype=int)
    for i in range(num_consultants):
        rating[i, 0] = technical_expertise[i]
        rating[i, 1] = leadership_capability[i]
        rating[i, 2] = innovation_capacity[i]
        rating[i, 3] = communication_proficiency[i]

    mean_total_scaled = np.zeros(num_dimensions, dtype=int)
    for d in range(num_dimensions):
        total_score = sum(rating[i, d] for i in range(num_consultants))
        mean_total_scaled[d] = total_score

    model = cp_model.CpModel()

    assign = {}
    for i in range(num_consultants):
        for t in range(num_teams):
            assign[(i, t)] = model.NewBoolVar(f"assign_{i}_{t}")

    for i in range(num_consultants):
        model.Add(sum(assign[(i, t)] for t in range(num_teams)) == 1)

    for t in range(num_teams):
        model.Add(sum(assign[(i, t)] for i in range(num_consultants)) == team_size)

    team_total_scaled = {}
    for d in range(num_dimensions):
        for t in range(num_teams):
            expr = sum(rating[i, d] * assign[(i, t)] * num_teams for i in range(num_consultants))
            team_total_scaled[(d, t)] = model.NewIntVar(0, 5 * team_size * num_teams, f"team_total_scaled_{d}_{t}")
            model.Add(team_total_scaled[(d, t)] == expr)

    abs_dev_scaled = {}
    for d in range(num_dimensions):
        for t in range(num_teams):
            dev_scaled = model.NewIntVar(-5 * team_size * num_teams, 5 * team_size * num_teams, f"dev_scaled_{d}_{t}")
            model.Add(dev_scaled == team_total_scaled[(d, t)] - mean_total_scaled[d])

            abs_dev_scaled[(d, t)] = model.NewIntVar(0, 5 * team_size * num_teams, f"abs_dev_scaled_{d}_{t}")
            model.AddAbsEquality(abs_dev_scaled[(d, t)], dev_scaled)

    total_imbalance_scaled = model.NewIntVar(0, 4 * num_teams * 5 * team_size * num_teams, "total_imbalance_scaled")
    model.Add(total_imbalance_scaled == sum(abs_dev_scaled[(d, t)] for d in range(num_dimensions) for t in range(num_teams)))
    model.Minimize(total_imbalance_scaled)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        consultant_team_assignment = []
        for i in range(num_consultants):
            for t in range(num_teams):
                if solver.Value(assign[(i, t)]) == 1:
                    consultant_team_assignment.append(t)
                    break

        total_imbalance_scaled_value = solver.Value(total_imbalance_scaled)
        total_imbalance_value = total_imbalance_scaled_value / num_teams

        print(json.dumps({
            "consultant_team_assignment": consultant_team_assignment,
            "total_competency_imbalance": total_imbalance_value
        }))

    else:
        print(json.dumps({
            "consultant_team_assignment": [],
            "total_competency_imbalance": None
        }))

if __name__ == "__main__":
    main()
